571	    private String correctText(String text){
572	        String correctedText = text;
573	
574	        //sometimes, even if timestamps are deactivated, Whisper insert those anyway (es. <|0.00|>), so we remove eventual timestamps
575	        String regex = "<\\|[^>]*\\|> ";    //with this regex we remove all substrings of the form "<|something|> "
576	        correctedText = correctedText.replaceAll(regex, "");
577	
578	        //we remove eventual white space from both ends of the text
579	        correctedText = correctedText.trim();
580	
581	        if(correctedText.length() >= 2) {
582	            //if the correctedText start with a lower case letter we make it upper case
583	            char firstChar = correctedText.charAt(0);
584	            if (Character.isLowerCase(firstChar)) {
585	                StringBuilder sb = new StringBuilder(correctedText);
586	                sb.setCharAt(0, Character.toUpperCase(firstChar));
587	                correctedText = sb.toString();
588	            }
589	            //if the correctedText contains a "..." we remove it
590	            correctedText = correctedText.replace("...", "");
591	        }
592	        return correctedText;
593	    }
